/**
 * Values match @react-native-firebase/messaging AuthorizationStatus.
 * NOT_DETERMINED is -1, so a permission read must not use -1 as a timeout sentinel.
 */
export const NotificationAuthorizationStatus = {
  NOT_DETERMINED: -1,
  DENIED: 0,
  AUTHORIZED: 1,
  PROVISIONAL: 2,
  EPHEMERAL: 3,
} as const;

export function isNotificationPermissionGranted(status: number | boolean): boolean {
  if (typeof status === 'boolean') {
    return status;
  }
  return (
    status === NotificationAuthorizationStatus.AUTHORIZED ||
    status === NotificationAuthorizationStatus.PROVISIONAL ||
    status === NotificationAuthorizationStatus.EPHEMERAL
  );
}

import {isNotificationPermissionGranted, NotificationAuthorizationStatus} from './notificationPermission';

describe('isNotificationPermissionGranted', () => {
  it('treats authorized, provisional, and ephemeral as granted', () => {
    expect(isNotificationPermissionGranted(NotificationAuthorizationStatus.AUTHORIZED)).toBe(true);
    expect(isNotificationPermissionGranted(NotificationAuthorizationStatus.PROVISIONAL)).toBe(true);
    expect(isNotificationPermissionGranted(NotificationAuthorizationStatus.EPHEMERAL)).toBe(true);
    expect(isNotificationPermissionGranted(true)).toBe(true);
  });

  it('does not treat not-determined or denied as granted', () => {
    expect(isNotificationPermissionGranted(NotificationAuthorizationStatus.NOT_DETERMINED)).toBe(false);
    expect(isNotificationPermissionGranted(NotificationAuthorizationStatus.DENIED)).toBe(false);
    expect(isNotificationPermissionGranted(false)).toBe(false);
  });
});

